    "reputation": {
      "scale": [
        1,
        5
      ],
      "initial": 1,
      "floor": 1,
      "ceiling": 5,
      "neutral": 3,
      "effectPerPoint": 0.15,
      "note": "顾客给店铺打分，与外卖平台的商家评分同一套做法：每交付一台就留下一条评价，店铺的分是这些评价的加权平均。所以它随每一单跳动，而且单子越多越难被少数几条好评拉起来。初始 1 分，因为一条评价都没有。",
      "model": "weighted_average_of_reviews",
      "priorWeight": 3,
      "priorNote": "开局按 3 条 1 分评价计入，等价于「没有记录就不该有好名声」。它决定新店要多少单才能把分数拉上来。",
      "reviews": {
        "met": {
          "3": 0.4,
          "4": 0.4,
          "5": 0.2
        },
        "exceeded": {
          "3": 0.1,
          "4": 0.4,
          "5": 0.5
        },
        "late": {
          "2": 0.5,
          "3": 0.5
        },
        "missed": {
          "1": 0.4,
          "2": 0.6
        }
      },
      "reviewsNote": "达标时 3 分保底、有机会拿到 4 与 5；超额完成时 5 分的比例大幅上升；迟交与让客户失望则落在 1—3 分。每一条评价都是随机的，所以店铺的分会自然跳动。"
    },
    "priceAcceptance": {
      "formula": "ratio = price / reference; below reference: clamp(1 + belowSlope*(1-ratio), 1, ceiling); above reference: clamp(1 - aboveSlope*(ratio-1), floor, 1)",
      "marketReferencePrice": "midpoint of the archetype budget range",
      "aboveSlopeBySegment": {
        "mass": 4,
        "bespoke": 3
      },
      "belowSlope": 2,
      "floor": 0.1,
      "ceiling": 1.3,
      "budgetCeiling": "A price above the archetype budget maximum never sells, whatever the acceptance value.",
      "note": "斜率按细分市场标定：量产客群极度价格敏感（现实里大厂毛利被压到 13%），高定客群对价格不敏感。斜率取值保证有效贡献在接近市场参考价处最高，加价不能无脑赚钱 接受度还会乘以外观偏好系数，见 appearancePreference"
    },
    "fit": {
      "formula": "clamp(actualUseCaseScore / expectedScore, 0, 1)",
      "note": "用途适配 F 只看得分；硬性要求不满足时订单直接不成交，不由 F 补偿"
    },
    "monthlyVolume": {
      "source": "design/economy-candidate.json companyDemandCaps",
      "splitRule": "Each segment's monthly cap is split across its archetypes in proportion to weight."
    },
